import{_ as s,o as a,c as e,S as n}from"./chunks/framework.df611035.js";const l=JSON.parse('{"title":"Portal Dev 门户联调工具","description":"","frontmatter":{},"headers":[],"relativePath":"components/portalDev/home.md","filePath":"components/portalDev/home.md","lastUpdated":1787377856000}'),o=[n('<h1 id="portal-dev-门户联调工具" tabindex="-1">Portal Dev 门户联调工具 <a class="header-anchor" href="#portal-dev-门户联调工具" aria-label="Permalink to &quot;Portal Dev 门户联调工具&quot;">​</a></h1><p><code>@sybz-components/portal-dev</code> 是成华、石景山门户自动登录与本地前端联调 CLI。它属于 <code>sybz-components</code> 工具生态，但作为独立 npm 包发布，不会增加组件主包的浏览器端体积。</p><h2 id="能力" tabindex="-1">能力 <a class="header-anchor" href="#能力" aria-label="Permalink to &quot;能力&quot;">​</a></h2><ul><li>自动启动目标项目的开发服务。</li><li>自动填写门户账号和密码。</li><li>自动识别图形验证码并登录。</li><li>石景山门户可进入智能体样板间，获取门户 Token 后打开本地页面。</li><li>成华门户可在登录成功后进入智能体广场。</li><li>随包提供 Codex <code>portal-dev</code> Skill。</li></ul><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li>Node.js 18+</li><li>Google Chrome 或 Microsoft Edge</li><li>目标项目已安装依赖，并提供 <code>dev</code> script</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">pnpm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">add</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">-D</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">@sybz-components/portal-dev</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">pnpm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">add</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">-D</span><span style="color:#24292E;"> </span><span style="color:#032F62;">@sybz-components/portal-dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>需要在任意目录直接使用时，也可以全局安装：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">pnpm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">add</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">-g</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">@sybz-components/portal-dev</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">pnpm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">add</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">-g</span><span style="color:#24292E;"> </span><span style="color:#032F62;">@sybz-components/portal-dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>在业务项目的 <code>.env.local</code> 中配置个人账号：</p><div class="language-dotenv vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">SJS_PORTAL_USERNAME=</span></span>\n<span class="line"><span style="color:#e1e4e8;">SJS_PORTAL_PASSWORD=</span></span>\n<span class="line"><span style="color:#e1e4e8;"></span></span>\n<span class="line"><span style="color:#e1e4e8;">CHENGHUA_PORTAL_USERNAME=</span></span>\n<span class="line"><span style="color:#e1e4e8;">CHENGHUA_PORTAL_PASSWORD=</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">SJS_PORTAL_USERNAME=</span></span>\n<span class="line"><span style="color:#24292e;">SJS_PORTAL_PASSWORD=</span></span>\n<span class="line"><span style="color:#24292e;"></span></span>\n<span class="line"><span style="color:#24292e;">CHENGHUA_PORTAL_USERNAME=</span></span>\n<span class="line"><span style="color:#24292e;">CHENGHUA_PORTAL_PASSWORD=</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>.env.local</code> 不应提交到 Git。CLI 会读取目标项目的 <code>.env.local</code>、<code>.env</code> 和进程环境变量。</p><h2 id="石景山门户联调" tabindex="-1">石景山门户联调 <a class="header-anchor" href="#石景山门户联调" aria-label="Permalink to &quot;石景山门户联调&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">pnpm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">exec</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">portal-dev</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">--portal</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">sjs</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">--project</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">.</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">pnpm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">exec</span><span style="color:#24292E;"> </span><span style="color:#032F62;">portal-dev</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">--portal</span><span style="color:#24292E;"> </span><span style="color:#032F62;">sjs</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">--project</span><span style="color:#24292E;"> </span><span style="color:#032F62;">.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>默认流程：</p><ol><li>检查 <code>http://localhost:5173</code> 是否已经启动。</li><li>未启动时执行目标项目的 <code>dev</code> script。</li><li>打开石景山门户并自动登录。</li><li>进入智能体样板间并搜索 <code>3D智能展厅智能体</code>。</li><li>获取门户页面中的 Token，并打开对应的本地页面。</li></ol><p>Token 不会输出到终端，也不会写入文件。</p><h2 id="成华门户登录" tabindex="-1">成华门户登录 <a class="header-anchor" href="#成华门户登录" aria-label="Permalink to &quot;成华门户登录&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">pnpm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">exec</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">portal-dev</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">--portal</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">chenghua</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">--project</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">.</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">pnpm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">exec</span><span style="color:#24292E;"> </span><span style="color:#032F62;">portal-dev</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">--portal</span><span style="color:#24292E;"> </span><span style="color:#032F62;">chenghua</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">--project</span><span style="color:#24292E;"> </span><span style="color:#032F62;">.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>成华模式只完成门户登录，并进入智能体广场，不启动本地项目、不执行石景山样板间跳转流程。</p><h2 id="添加项目命令" tabindex="-1">添加项目命令 <a class="header-anchor" href="#添加项目命令" aria-label="Permalink to &quot;添加项目命令&quot;">​</a></h2><p>在业务项目的 <code>package.json</code> 中添加：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">{</span></span>\n<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;scripts&quot;</span><span style="color:#E1E4E8;">: {</span></span>\n<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#79B8FF;">&quot;dev:portal&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;portal-dev --portal sjs --project .&quot;</span><span style="color:#E1E4E8;">,</span></span>\n<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#79B8FF;">&quot;dev:portal:chenghua&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;portal-dev --portal chenghua --project .&quot;</span></span>\n<span class="line"><span style="color:#E1E4E8;">  }</span></span>\n<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">{</span></span>\n<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;scripts&quot;</span><span style="color:#24292E;">: {</span></span>\n<span class="line"><span style="color:#24292E;">    </span><span style="color:#005CC5;">&quot;dev:portal&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;portal-dev --portal sjs --project .&quot;</span><span style="color:#24292E;">,</span></span>\n<span class="line"><span style="color:#24292E;">    </span><span style="color:#005CC5;">&quot;dev:portal:chenghua&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;portal-dev --portal chenghua --project .&quot;</span></span>\n<span class="line"><span style="color:#24292E;">  }</span></span>\n<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>使用：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">pnpm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">dev:portal</span></span>\n<span class="line"><span style="color:#B392F0;">pnpm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">dev:portal:chenghua</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">pnpm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">dev:portal</span></span>\n<span class="line"><span style="color:#6F42C1;">pnpm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">dev:portal:chenghua</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="安装-codex-skill" tabindex="-1">安装 Codex Skill <a class="header-anchor" href="#安装-codex-skill" aria-label="Permalink to &quot;安装 Codex Skill&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">pnpm</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">exec</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">portal-dev</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">skill</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">install</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">pnpm</span><span style="color:#24292E;"> </span><span style="color:#032F62;">exec</span><span style="color:#24292E;"> </span><span style="color:#032F62;">portal-dev</span><span style="color:#24292E;"> </span><span style="color:#032F62;">skill</span><span style="color:#24292E;"> </span><span style="color:#032F62;">install</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Skill 默认安装到 <code>~/.codex/skills/portal-dev</code>。安装后可以让 Codex 直接执行：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">使用 portal-dev 启动当前项目的石景山门户联调</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">使用 portal-dev 启动当前项目的石景山门户联调</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">使用 portal-dev 登录成华门户</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">使用 portal-dev 登录成华门户</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><table><thead><tr><th>参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>--portal</code></td><td><code>sjs</code></td><td>门户类型，可选 <code>sjs</code>、<code>chenghua</code></td></tr><tr><td><code>--project</code></td><td>当前目录</td><td>目标前端项目路径</td></tr><tr><td><code>--login-only</code></td><td>成华默认启用</td><td>只登录门户，不启动本地联调</td></tr><tr><td><code>--help</code></td><td>-</td><td>查看命令帮助</td></tr></tbody></table><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><table><thead><tr><th>变量</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>SJS_PORTAL_USERNAME</code></td><td>无</td><td>石景山用户名，必填</td></tr><tr><td><code>SJS_PORTAL_PASSWORD</code></td><td>无</td><td>石景山密码，必填</td></tr><tr><td><code>CHENGHUA_PORTAL_USERNAME</code></td><td>无</td><td>成华用户名，必填</td></tr><tr><td><code>CHENGHUA_PORTAL_PASSWORD</code></td><td>无</td><td>成华密码，必填</td></tr><tr><td><code>SJS_PORTAL_LOGIN_URL</code></td><td>内置登录页</td><td>石景山门户登录地址</td></tr><tr><td><code>CHENGHUA_PORTAL_LOGIN_URL</code></td><td>内置登录页</td><td>成华门户登录地址</td></tr><tr><td><code>CHENGHUA_PORTAL_AFTER_LOGIN_URL</code></td><td>成华智能体广场</td><td>成华登录后的页面</td></tr><tr><td><code>PORTAL_LOCAL_ORIGIN</code></td><td><code>http://localhost:5173</code></td><td>本地开发服务地址</td></tr><tr><td><code>PORTAL_IFRAME_HOST</code></td><td>内置石景山域名</td><td>目标 iframe 域名</td></tr><tr><td><code>PORTAL_IFRAME_PATH</code></td><td><code>/exhibition-hall</code></td><td>目标智能体路径</td></tr><tr><td><code>PORTAL_ROOM_NAME</code></td><td><code>3D智能展厅智能体</code></td><td>样板间智能体名称</td></tr><tr><td><code>PORTAL_PROJECT_DIR</code></td><td>当前目录</td><td>目标项目路径</td></tr><tr><td><code>CHROME_PATH</code></td><td>自动查找</td><td>Chrome 或 Edge 路径</td></tr></tbody></table><p>旧项目中的 <code>PORTAL_USERNAME</code>、<code>PORTAL_PASSWORD</code>、<code>PORTAL_LOGIN_URL</code> 仍可用于石景山门户。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="提示缺少账号密码" tabindex="-1">提示缺少账号密码 <a class="header-anchor" href="#提示缺少账号密码" aria-label="Permalink to &quot;提示缺少账号密码&quot;">​</a></h3><p>确认变量写在目标业务项目的 <code>.env.local</code> 中，而不是组件库项目中，并确认命令的 <code>--project</code> 指向正确目录。</p><h3 id="找不到-chrome-或-edge" tabindex="-1">找不到 Chrome 或 Edge <a class="header-anchor" href="#找不到-chrome-或-edge" aria-label="Permalink to &quot;找不到 Chrome 或 Edge&quot;">​</a></h3><p>安装 Chrome/Edge，或者配置：</p><div class="language-dotenv vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">CHROME_PATH=/path/to/browser</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">CHROME_PATH=/path/to/browser</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="本地服务启动超时" tabindex="-1">本地服务启动超时 <a class="header-anchor" href="#本地服务启动超时" aria-label="Permalink to &quot;本地服务启动超时&quot;">​</a></h3><p>确认业务项目存在 <code>dev</code> script。默认使用 <code>5173</code> 端口；使用其他地址时配置：</p><div class="language-dotenv vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">PORTAL_LOCAL_ORIGIN=http://localhost:你的端口</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">PORTAL_LOCAL_ORIGIN=http://localhost:你的端口</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="验证码识别失败" tabindex="-1">验证码识别失败 <a class="header-anchor" href="#验证码识别失败" aria-label="Permalink to &quot;验证码识别失败&quot;">​</a></h3><p>CLI 最多自动尝试三次。连续失败时可以重新运行命令，或检查门户验证码样式是否已经发生变化。</p>',48)],p=s({name:"components/portalDev/home.md"},[["render",function(s,n,l,p,t,c){return a(),e("div",null,o)}]]);export{l as __pageData,p as default};
